namespace moon {namespace {using namespace ase;
struct Item {const timeline::Layer* layer=nullptr;const timeline::Group* group=nullptr;unsigned level=0;};
std::vector<Item> ordered(const timeline::State& s){std::map<std::string,const timeline::Group*> groups;std::map<std::string,double> order;for(const auto& g:s.groups)groups[g.id]=&g;
 std::function<double(const std::string&,std::set<std::string>)> anchor=[&](const std::string& id,std::set<std::string> path){auto cached=order.find(id);if(cached!=order.end())return cached->second;if(!path.insert(id).second)bad("ASE 组层级成环。");double result=std::numeric_limits<double>::infinity();for(std::size_t k=0;k<s.layers.size();k++)if(s.layers[k].groupId==std::optional<std::string>(id))result=std::min(result,double(s.layers.size()-1-k));for(const auto& g:s.groups)if(g.parentGroupId==std::optional<std::string>(id))result=std::min(result,anchor(g.id,path));order[id]=result;return result;};std::vector<Item> out;std::set<std::string> seen;struct SortItem {Item item;double order;std::size_t tie;};
 std::function<void(std::optional<std::string>,unsigned)> visit=[&](std::optional<std::string> parent,unsigned level){std::vector<SortItem> items;for(std::size_t k=0;k<s.layers.size();k++){const auto& l=s.layers[k];auto owner=l.groupId&&groups.count(*l.groupId)?l.groupId:std::nullopt;if(owner==parent)items.push_back({{&l,nullptr,level},double(s.layers.size()-1-k),0});}for(std::size_t k=0;k<s.groups.size();k++){const auto& g=s.groups[k];auto owner=g.parentGroupId&&groups.count(*g.parentGroupId)&&*g.parentGroupId!=g.id?g.parentGroupId:std::nullopt;if(owner==parent)items.push_back({{nullptr,&g,level},anchor(g.id,{}),k});}std::stable_sort(items.begin(),items.end(),[](const auto& a,const auto& b){return a.order==b.order?a.tie<b.tie:a.order<b.order;});for(const auto& v:items){out.push_back(v.item);if(v.item.group){if(!seen.insert(v.item.group->id).second)bad("ASE 重复图层组。");visit(v.item.group->id,level+1);}}};visit(std::nullopt,0);if(out.size()!=s.layers.size()+s.groups.size())bad("ASE 组层级无效。");return out;}
void layerChunk(Writer& chunks,const Item& item){Writer p;bool group=item.group!=nullptr;const auto visible=group?item.group->visible:item.layer->visible,locked=group?item.group->locked:item.layer->locked;p.u16((visible?1:0)|(locked?0:2));p.u16(group?1:0);p.u16(item.level);p.zero(4);p.u16(blend(group?item.group->blendMode:item.layer->blendMode));p.u8(group?alpha(item.group->opacity):255);p.zero(3);p.str(group?item.group->name:item.layer->name);chunks.chunk(0x2004,p);}
void celChunk(Writer& chunks,unsigned layerIndex,const timeline::Surface& source,double scale,double opacity,int z,std::optional<unsigned> linked){if(source.width<1||source.height<1||source.pixels.size()!=std::size_t(source.width)*source.height)bad("ASE 源 cel 像素无效。");auto left=std::floor(source.offsetX*scale),top=std::floor(source.offsetY*scale),right=std::ceil((double(source.offsetX)+source.width)*scale),bottom=std::ceil((double(source.offsetY)+source.height)*scale);auto width=std::max(1.,right-left),height=std::max(1.,bottom-top);if(left< -32768||left>32767||top< -32768||top>32767||width>65535||height>65535||width*height>Budget/4)bad("ASE 缩放后 cel 尺寸或偏移超限。");Writer p;p.u16(layerIndex);p.u16(unsigned(int(left)));p.u16(unsigned(int(top)));p.u8(alpha(opacity));p.u16(linked?1:2);p.u16(unsigned(std::clamp(z,-32768,32767)));p.zero(5);if(linked)p.u16(*linked);else{p.u16(unsigned(width));p.u16(unsigned(height));Writer data;data.b.reserve(std::size_t(width*height)*4);for(int y=0;y<int(height);y++)for(int x=0;x<int(width);x++){auto sx=std::clamp(int(std::floor((left+x+.5)/scale-source.offsetX)),0,source.width-1),sy=std::clamp(int(std::floor((top+y+.5)/scale-source.offsetY)),0,source.height-1);data.u32(source.pixels[std::size_t(sy)*source.width+sx]);}p.raw(deflate(data.b));}chunks.chunk(0x2005,p);}
}
std::u32string asepriteExportNotice(const Document& document){std::u32string notice=U"ASE 导出整个工程及全部帧。文字、背景与关联图层以栅格像素保存；调色板布局、切片、帧禁用状态及 MoonSprite 专用编辑信息不会写入 ASE。";if(!document.timeline().state().masks.empty())notice+=U" 此工程含蒙版，将按每帧合成为一个图层，保留画面并失去独立图层与蒙版编辑能力。";return notice;}
std::vector<std::uint8_t> encodeAseprite(const Document& document,int scalePercent){using namespace ase;const auto& timeline=document.timeline();const auto& state=timeline.state();if(state.frames.empty()||state.frames.size()>65535||state.loopSections.size()>65535||!timeline.diagnoseLinks().empty())bad("ASE 时间轴关系或帧数无效。");double scale=std::clamp(scalePercent/100.,.01,64.);int width=std::max(1,int(std::floor(document.width()*scale+.5))),height=std::max(1,int(std::floor(document.height()*scale+.5)));if(width>65535||height>65535)bad("ASE 导出画布尺寸超限。");bool composite=!state.masks.empty();timeline::Layer compositeLayer;compositeLayer.id="ase-composite";compositeLayer.name=document.name();auto items=composite?std::vector<Item>{{&compositeLayer,nullptr,0}}:ordered(state);if(items.empty()||items.size()>65535)bad("ASE 图层数量无效。");for(const auto& layer:state.layers)if(!layer.kind.empty()&&layer.kind!="text")bad("ASE 包含尚未迁移的图层类型。");Writer first;unsigned firstCount=0;for(const auto& item:items){layerChunk(first,item);firstCount++;}
 if(!state.loopSections.empty()){Writer tags;tags.u16(unsigned(state.loopSections.size()));tags.zero(8);for(const auto& section:state.loopSections){auto range=timeline::loopRange(state,section);if(range.start<0||range.end<range.start||range.end>=int(state.frames.size()))bad("ASE 标签范围无效。");tags.u16(unsigned(range.start));tags.u16(unsigned(range.end));unsigned direction=section.direction=="ping-pong-reverse"?3:section.direction=="ping-pong"?2:section.direction=="reverse"?1:0;tags.u8(direction);tags.u16(unsigned(section.repeatCount?std::clamp(*section.repeatCount,1,65535):0));tags.zero(10);tags.str(section.name);}first.chunk(0x2018,tags);firstCount++;}
 Writer out;out.u32(0);out.u16(0xa5e0);out.u16(unsigned(state.frames.size()));out.u16(unsigned(width));out.u16(unsigned(height));out.u16(32);out.u32(3);out.u16(unsigned(std::clamp(state.frames[0].duration,1,65535)));out.zero(14);out.u8(1);out.u8(1);out.zero(4);out.u16(16);out.u16(16);out.zero(84);
 for(std::size_t fi=0;fi<state.frames.size();fi++){Writer chunks;unsigned count=0;if(fi==0){chunks.raw(first.b);count=firstCount;}for(unsigned li=0;li<items.size();li++){if(items[li].group)continue;const auto& layer=*items[li].layer;timeline::Surface baked;const timeline::Surface* surface=nullptr;double opacity=1;int z=0;std::optional<unsigned> linked;if(composite){baked.width=document.width();baked.height=document.height();baked.pixels=compositeNormalRegion(timeline,state.frames[fi].id,{0,0,baked.width,baked.height});surface=&baked;}else{const auto* cel=timeline.findCel(layer.id,state.frames[fi].id);if(cel){auto resolved=timeline.resolveSurface(cel->id);if(resolved.issue!=timeline::LinkIssue::None)bad("ASE cel 链接无效。");surface=resolved.surface;opacity=frameCelOpacity(timeline,layer,state.frames[fi].id);z=cel->zIndex;if(cel->linkedCelId&&resolved.source){auto sourceIndex=timeline.frameIndex(resolved.source->frameId);if(sourceIndex<fi)linked=unsigned(sourceIndex);}}if(!surface){baked.width=baked.height=1;baked.pixels.assign(1,0);surface=&baked;}}celChunk(chunks,li,*surface,scale,opacity,z,linked);count++;}out.u32(std::uint32_t(16+chunks.b.size()));out.u16(0xf1fa);out.u16(count<65535?count:65535);out.u16(unsigned(std::clamp(state.frames[fi].duration,1,65535)));out.u16(0);out.u32(count<65535?0:count);out.raw(chunks.b);}out.patch32(0,std::uint32_t(out.b.size()));return out.b;}
}